// Example Program.cs snippet to wire up JWT, role-based authorization and environment-aware CORS
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.Text;

var builder = WebApplication.CreateBuilder(args);
// Configuration: read from secure config or environment variables
var jwtKey = builder.Configuration["Jwt:Key"] ?? throw new InvalidOperationException("JWT key not configured");
var jwtIssuer = builder.Configuration["Jwt:Issuer"];
var allowedOrigins = builder.Environment.IsDevelopment() ? new[] {

 } : builder.Configuration.GetSection("Cors:AllowedOrigins").Get<string[]>();

// Authentication
builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
}).AddJwtBearer(options =>
{
    options.RequireHttpsMetadata = true; // enforce https in prod
    options.SaveToken = true;
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = false,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
        ValidIssuer = jwtIssuer,
        IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey))
    };
});

// Authorization: role-based policies
builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("RequireAdminRole", policy => policy.RequireRole("Admin"));
    options.AddPolicy("RequireUserRole", policy => policy.RequireRole("User", "Admin"));
});

// CORS: environment-aware and restricted in production
builder.Services.AddCors(options =>
{
    options.AddPolicy(name: "AppCorsPolicy", builder =>
    {
        if (allowedOrigins != null && allowedOrigins.Length > 0)
        {
            builder.WithOrigins(allowedOrigins)
                   .AllowAnyHeader()
                   .AllowAnyMethod()
                   .AllowCredentials();
        }
        else
        {
            // Fallback to a safe default: deny all cross-origin requests
            builder.SetIsOriginAllowed(_ => false);
        }
    });
});

var app = builder.Build();

app.UseHttpsRedirection();
app.UseRouting();
app.UseCors("AppCorsPolicy");
app.UseAuthentication();
app.UseAuthorization();

// Example of applying role-based authorization on endpoints
app.MapControllers().RequireAuthorization(); // or map specific endpoints with .RequireAuthorization(
